import type {
  CurriculumLesson,
  CurriculumUnit,
  FlashcardContent,
  PracticeItem,
  QuizQuestion,
  StandardReference,
} from "./curriculumSchema.ts";
import { CURRICULUM_SCHEMA_VERSION } from "./curriculumSchema.ts";
import type { LibraryGrade, LibrarySubject } from "./studyLibrary.ts";

type QuestionSpec = { prompt: string; answer: string; distractors: string[]; explanation: string; difficulty?: QuizQuestion["difficulty"] };
type LessonSpec = {
  title: string;
  objective: string;
  concept: string;
  conceptDescription: string;
  prerequisite: string;
  teacher: string;
  student: string;
  examplePrompt: string;
  exampleSteps: string[];
  exampleAnswer: string;
  guided: Array<{ prompt: string; answer: string; feedback: string; hint?: string }>;
  independent: Array<{ prompt: string; answer: string; feedback: string; hint?: string }>;
  misconception: string;
  repairPrompt: string;
  repairAnswer: string;
  repair: string;
  exitPrompt: string;
  exitAnswer: string;
  flashcards: Array<{ front: string; back: string }>;
  questions: QuestionSpec[];
  readAloud: string[];
  simplified: string;
  visual: string;
  interaction: string;
  remediation: string[];
  extension: string[];
};

const originalSource = { kind: "ORIGINAL" as const, attribution: "StudySmart Originals", license: "StudySmart Original · educator-reviewed pilot", reviewedBy: "StudySmart Curriculum Review Board" };

function practiceItems(prefix: string, items: LessonSpec["guided"]): PracticeItem[] {
  return items.map((item, index) => ({ id: `${prefix}-${index + 1}`, ...item }));
}

function makeLesson(unitId: string, grade: LibraryGrade, subject: LibrarySubject, sequence: number, standards: StandardReference[], spec: LessonSpec): CurriculumLesson {
  const conceptId = `${unitId}-concept-${sequence}`;
  const flashcards: FlashcardContent[] = spec.flashcards.map((card, index) => ({ id: `${unitId}-l${sequence}-f${index + 1}`, front: card.front, back: card.back, conceptId }));
  const quizQuestions: QuizQuestion[] = spec.questions.map((question, index) => {
    const raw = [question.answer, ...question.distractors].slice(0, 4);
    const answerIndex = (sequence + index) % raw.length;
    const options = raw.map((_, optionIndex) => raw[(optionIndex - answerIndex + raw.length) % raw.length]);
    return { id: `${unitId}-l${sequence}-q${index + 1}`, prompt: question.prompt, options, answerIndex, explanation: question.explanation, conceptId, difficulty: question.difficulty ?? (index === 0 ? "RECALL" : index === 1 ? "APPLY" : "TRANSFER") };
  });
  return {
    id: `${unitId}-lesson-${sequence}`,
    unitId,
    version: 1,
    schemaVersion: CURRICULUM_SCHEMA_VERSION,
    status: "PUBLISHED",
    sequence,
    title: spec.title,
    grade,
    subject,
    learningObjective: spec.objective,
    prerequisiteConcepts: [{ id: `${unitId}-prerequisite-${sequence}`, name: spec.prerequisite, description: `A learner uses ${spec.prerequisite.toLocaleLowerCase()} before this lesson.` }],
    concepts: [{ id: conceptId, name: spec.concept, description: spec.conceptDescription, prerequisiteIds: [`${unitId}-prerequisite-${sequence}`] }],
    standards,
    teacherExplanation: spec.teacher,
    studentExplanation: spec.student,
    workedExample: { prompt: spec.examplePrompt, steps: spec.exampleSteps, answer: spec.exampleAnswer, whyItWorks: `The steps make the idea visible and connect the model to the answer: ${spec.exampleAnswer}.` },
    guidedPractice: practiceItems(`${unitId}-l${sequence}-g`, spec.guided),
    independentPractice: practiceItems(`${unitId}-l${sequence}-i`, spec.independent),
    misconceptionChecks: [{ id: `${unitId}-l${sequence}-m1`, misconception: spec.misconception, prompt: spec.repairPrompt, expectedResponse: spec.repairAnswer, repair: spec.repair }],
    exitTicket: { prompt: spec.exitPrompt, answer: spec.exitAnswer, successCriteria: `The learner answers accurately and explains the idea using ${spec.concept.toLocaleLowerCase()}.` },
    flashcards,
    quizQuestions,
    readAloudScript: spec.readAloud,
    accessibilityAlternatives: { visualDescription: spec.visual, readAloud: spec.readAloud.join(" "), simplifiedLanguage: spec.simplified, interactionAlternative: spec.interaction, supports: ["captions", "keyboard navigation", "high contrast", "reduced motion"] },
    remediationPath: { when: "The learner misses the exit ticket or fewer than two independent items.", steps: spec.remediation, nextLessonId: sequence > 1 ? `${unitId}-lesson-${sequence - 1}` : undefined },
    extensionPath: { when: "The learner meets the exit-ticket criteria and explains why the answer works.", steps: spec.extension, nextLessonId: sequence < 10 ? `${unitId}-lesson-${sequence + 1}` : undefined },
    masteryEvidenceRules: { threshold: 0.8, minimumIndependentItems: 2, requiredExitTicket: true, evidenceTypes: ["GUIDED", "INDEPENDENT", "MISCONCEPTION_REPAIR", "EXIT_TICKET", "QUIZ", "FLASHCARD"], nextReviewDays: [1, 3, 7, 14] },
    reviewSchedule: { initialDays: 1, intervalsDays: [1, 3, 7, 14, 30], retentionTarget: 0.9 },
    source: originalSource,
    authoringNotes: "Pilot authored against the shared StudySmart lesson schema; AI may propose variants, but this published version is educator-reviewed.",
  };
}

function unit(id: string, title: string, description: string, grade: LibraryGrade, subject: LibrarySubject, standards: StandardReference[], prerequisites: string[], specs: LessonSpec[]): CurriculumUnit {
  const prerequisiteConcepts = prerequisites.map((name, index) => ({ id: `${id}-unit-prerequisite-${index + 1}`, name, description: `Prior knowledge needed for ${title}.` }));
  return { id, version: 1, status: "PUBLISHED", title, description, grade, subject, standards, prerequisiteConcepts, lessons: specs.map((spec, index) => makeLesson(id, grade, subject, index + 1, standards, spec)), source: originalSource };
}

