export function listPilotUnits(filters?: { grade?: LibraryGrade; subject?: LibrarySubject }) {
  return PILOT_UNITS.filter((unit) => (!filters?.grade || unit.grade === filters.grade) && (!filters?.subject || unit.subject === filters.subject));
}

export function getPilotLesson(lessonId: string) {
  return PILOT_UNITS.flatMap((unit) => unit.lessons).find((lesson) => lesson.id === lessonId) ?? null;
}
